 "content": "def transform(grid):
    """Replace embedded, large solid-color rectangular patches with 4."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    out = [row[:] for row in grid]
    # Mark cells belonging to any monochromatic rectangle of meaningful size.
    # The planted patches in this task are at least 24 cells (including 4x6).
    marked = [[False] * w for _ in range(h)]
    for top in range(h):
        for left in range(w):
            color = grid[top][left]
            run = [True] * w
            for bottom in range(top, h):
                for col in range(left, w):
                    if grid[bottom][col] != color:
                        run[col] = False
                height = bottom - top + 1
                if height < 4:
                    continue
                # Contiguous horizontal runs that remain all this color from top to bottom.
                col = left
                while col < w:
                    while col < w and not run[col]:
                        col += 1
                    start = col
                    while col < w and run[col]:
                        col += 1
                    width = col - start
                    if width >= 4 and height * width >= 24:
                        for r in range(top, bottom + 1):
                            for c in range(start, col):
                                marked[r][c] = True
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
